class Solution {
public:
    int numWays(vector<string>& words, string target) {
        const long long MOD = 1000000007;
        int L = words[0].size();
        int n = words.size();
        int m = target.size();

        vector<vector<int>> freq(L, vector<int>(26, 0));
        for (int k = 0; k < L; k++) {
            for (int j = 0; j < n; j++) {
                freq[k][words[j][k] - 'a']++;
            }
        }

        vector<long long> dp(m + 1, 0);
        dp[0] = 1;
        for (int k = 0; k < L; k++) {
            for (int i = m; i >= 1; i--) {
                int c = target[i - 1] - 'a';
                dp[i] = (dp[i] + dp[i - 1] * freq[k][c]) % MOD;
            }
        }
        return (int)dp[m];
    }
};
